<script setup lang="ts">
import { computed, ref } from 'vue'
import { onShow } from '@dcloudio/uni-app'
import AppPage from '../../components/AppPage.vue'
import Icon from '../../components/Icon.vue'
import EnergyRing from '../../components/EnergyRing.vue'
import NutrientBars from '../../components/NutrientBars.vue'
import TrendChart from '../../components/TrendChart.vue'
import { useHealthStore } from '../../stores/health'
import { dateKey, parseDate } from '../../domain/dates'
import { advice, metricRecords, total } from '../../domain/nutrition'
import { display, navigate } from '../../utils/ui'
const store = useHealthStore(), today=ref(dateKey())
onShow(()=>{store.hydrate();today.value=dateKey();if(!store.data.onboarded&&!store.storageIssue)uni.redirectTo({url:'/pages/welcome/index'})})
const entries=computed(()=>store.data.meals.filter(x=>x.date===today.value)), totals=computed(()=>total(entries.value))
const targets=computed(()=>store.data.profile.targets), tip=computed(()=>advice(store.data,today.value))
const weights=computed(()=>metricRecords(store.data.bodies,'weight',today.value,30))
const latest=computed(()=>[...store.data.bodies].filter(x=>x.weight!==undefined&&x.date<=today.value).sort((a,b)=>b.date.localeCompare(a.date))[0])
const change=computed(()=>weights.value.length>=2?weights.value[weights.value.length-1].weight!-weights.value[0].weight!:undefined)
const trainingToday=computed(()=>store.data.training.filter(x=>x.date===today.value))
const remaining=computed(()=>targets.value.kcal===undefined?undefined:targets.value.kcal-totals.value.kcal)
const dateText=computed(()=>`${parseDate(today.value).getMonth()+1}月${parseDate(today.value).getDate()}日 · 星期${'日一二三四五六'[parseDate(today.value).getDay()]}`)
const greeting = computed(()=>new Date().getHours()<11?'早上好':new Date().getHours()<18?'下午好':'晚上好')
function followTip(){if(tip.value.action==='设置目标')navigate('goals');else if(tip.value.action==='查看趋势')navigate('body');else if(tip.value.action==='查看饮食')uni.redirectTo({url:'/pages/diet/index'});else navigate('food',`date=${today.value}`)}
</script>
<template><AppPage tab="today"><view class="row-between welcome-row"><view class="greeting-block"><text class="eyebrow">{{ dateText }}</text><view class="row gap-8"><text class="page-title">{{ greeting }}，{{ store.data.profile.name || '朋友' }}</text><Icon name="sun" tone="orange" :size="25" /></view></view><button role="button" class="pill" @click="navigate('goals')"><view class="tag-dot" />{{ store.data.profile.goal }}</button></view>
  <view v-if="store.storageIssue" class="error-message">{{ store.storageIssue }}</view>
  <view class="energy-card card"><view class="row-between"><view class="row gap-8"><Icon name="fire" :size="17" /><text class="small-title">今日能量</text></view><button role="button" class="text-link gray" @click="navigate('goals')">目标设置<Icon name="arrow" tone="muted" :size="12" /></button></view><view class="energy-main"><EnergyRing :value="totals.kcal" :target="targets.kcal" /><view class="energy-side"><text class="side-label">每日目标</text><text class="target-number number">{{ display(targets.kcal) }}<text class="side-unit"> kcal</text></text><view class="energy-separator" /><text class="side-label">{{ remaining !== undefined && remaining < 0 ? '已超出目标' : '距离目标' }}</text><text class="remaining-number number" :class="{orange: remaining!==undefined && remaining<0}">{{ remaining===undefined?'—':Math.round(Math.abs(remaining)) }}<text class="side-unit"> kcal</text></text></view></view><NutrientBars :values="totals" :targets="targets" /><button role="button" v-if="!targets.kcal" class="target-hint text-link" @click="navigate('goals')">设置营养目标，查看每天的进度<Icon name="arrow" :size="12" /></button></view>
  <view class="quick-actions"><button role="button" class="btn-primary quick-main" @click="navigate('food',`date=${today}`)"><Icon name="plus" tone="white" :size="18" />记录饮食</button><button role="button" class="quick-sub" @click="navigate('body-entry')"><Icon name="scale" :size="20" /><text>记身体</text></button><button role="button" class="quick-sub" @click="navigate('training-entry')"><Icon name="dumbbell" :size="20" /><text>记训练</text></button></view>
  <view class="section"><view class="section-heading"><text class="section-title">身体的变化</text><button role="button" class="text-link" @click="navigate('body')">查看趋势<Icon name="arrow" :size="12" /></button></view><view class="weight-card" @click="navigate('body')"><view class="row-between"><view><text class="weight-caption">{{ latest ? '最近体重 · '+latest.date.slice(5).replace('-','.') : '我的体重' }}</text><text class="weight-number number">{{ display(latest?.weight,1) }}<text class="weight-unit">kg</text></text></view><view class="weight-change"><text class="change-number number">{{ change===undefined?'—':(change>0?'+':'')+change.toFixed(1) }}<text class="weight-unit">kg</text></text><text class="weight-caption">近30天记录变化</text></view></view><TrendChart :entries="weights" metric="weight" :end="today" :compact="true" /><view class="weight-foot"><text>允许波动，关注长期趋势</text><Icon name="arrow" :size="13" /></view></view></view>
  <view class="section"><view class="section-heading"><text class="section-title">给今天的一点建议</text><text class="section-caption">JUST FOR TODAY</text></view><view class="advice-card"><view class="advice-symbol"><Icon name="leaf" tone="orange" :size="21" /></view><view class="grow"><text class="advice-title">{{ tip.title }}</text><text class="advice-detail">{{ tip.detail }}</text><button role="button" class="text-link advice-action" @click="followTip">{{ tip.action }}<Icon name="arrow" :size="12" /></button></view></view></view>
  <view class="training-glance section" @click="navigate('training-entry')"><view class="row gap-12"><view class="training-glance-icon"><Icon name="dumbbell" :size="21" /></view><view><text class="small-title">{{ trainingToday.length ? '今天也为自己动起来了' : '动一动，找到自己的节奏' }}</text><text class="helper">{{ trainingToday.length ? `已记录 ${trainingToday.length} 次训练 · ${trainingToday.reduce((s,x)=>s+x.minutes,0)} 分钟` : '力量、慢跑或拉伸，每一种都值得记录' }}</text></view></view><Icon name="arrow" tone="muted" :size="15" /></view><view class="footer-note">每天一小步，身体会记得。<text class="footer-en">SMALL STEPS. REAL CHANGE.</text></view>
</AppPage></template>
<style scoped>.welcome-row{align-items:center;margin-bottom:24px}.welcome-row .eyebrow{font-size:10px;letter-spacing:1px;margin-bottom:9px}.welcome-row .page-title{font-size:24px}.energy-card{padding:20px 19px 22px;border-radius:22px}.small-title{font-size:13px;font-weight:550}.energy-main{display:flex;align-items:center;justify-content:space-evenly;gap:16px;padding:18px 0 23px}.energy-side{min-width:100px}.side-label{font-size:10px;color:var(--muted);display:block}.target-number{font-size:27px;font-weight:650;display:block;margin-top:6px}.side-unit{font-size:10px;color:var(--muted);font-weight:400;letter-spacing:0}.energy-separator{width:80px;height:1px;background:var(--line);margin:13px 0}.remaining-number{font-size:22px;font-weight:600;display:block;margin-top:5px;color:var(--green)}.target-hint{margin-top:19px;font-size:11px}.quick-actions{display:flex;align-items:center;gap:10px;margin-top:17px}.quick-main{flex:1;padding:14px 10px;font-size:13px}.quick-sub{display:flex;flex-direction:column;gap:6px;width:66px;font-size:10px;color:var(--green)}.weight-card{padding:20px 20px 14px;background:#e3ecda;border:1px solid #dce5d1;border-radius:19px}.weight-caption{display:block;font-size:10px;color:#798a70}.weight-number{display:block;font-size:32px;font-weight:650;margin-top:5px}.weight-unit{font-size:11px;color:#6e8167;letter-spacing:0;font-weight:400;margin-left:5px}.weight-change{text-align:right}.change-number{font-size:22px;display:block;color:var(--green);font-weight:500;margin-bottom:6px}.weight-foot{display:flex;justify-content:space-between;font-size:10px;color:#7a8c70;border-top:1px solid #cfdbc5;padding-top:11px;margin-top:2px}.advice-card{display:flex;gap:13px;padding:19px 16px;background:#fbf1e4;border:1px solid #f0dfc8;border-radius:17px}.advice-symbol{width:34px;height:34px;background:#fff7eb;border-radius:12px;display:flex;align-items:center;justify-content:center;flex-shrink:0}.advice-title{font-size:13px;font-weight:600;display:block;line-height:1.7}.advice-detail{font-size:11px;color:#998775;line-height:1.9;display:block;margin-top:6px}.advice-action{justify-content:flex-start;margin-top:10px;font-size:11px}.training-glance{display:flex;justify-content:space-between;align-items:center}.training-glance-icon{width:40px;height:40px;border-radius:14px;background:#e9eddf;display:flex;align-items:center;justify-content:center}.training-glance .small-title{font-size:12px}.training-glance .helper{font-size:10px;margin-top:5px}.footer-en{display:block;font-size:8px;letter-spacing:2px;margin-top:5px}.welcome-row{gap:10px}.greeting-block{flex:1;min-width:0}.greeting-block .page-title{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;min-width:0}.welcome-row .pill{flex-shrink:0;white-space:nowrap;padding:5px 10px;border-radius:20px;background:var(--sage);font-size:10px;color:var(--green)}@media(max-width:360px){.welcome-row .page-title{font-size:21px}.greeting-block .ui-icon{display:none}}</style>
